create type public.message_type as enum ('text', 'image', 'video', 'voice', 'activity_card');

-- The id is generated by the client so a retried send is a no-op.
create table public.messages (
  id uuid primary key,
  connection_id uuid not null references public.connections (id) on delete cascade,
  sender_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  type public.message_type not null,
  body text,
  media_key text,
  media_mime text,
  media_width integer,
  media_height integer,
  media_duration_ms integer,
  media_deleted_at timestamptz,
  activity_id uuid,
  removed_at timestamptz,
  created_at timestamptz not null default now(),
  check (type <> 'text' or coalesce(trim(body) <> '', false)),
  check (type not in ('image', 'video', 'voice') or media_key is not null),
  check (type <> 'video' or coalesce(media_duration_ms between 1 and 30000, false)),
  check (type <> 'voice' or coalesce(media_duration_ms between 1 and 120000, false)),
  check (type <> 'activity_card' or activity_id is not null)
);
create index on public.messages (connection_id, created_at);
alter table public.messages enable row level security;
revoke all on public.messages from anon, authenticated;
grant select on public.messages to authenticated;
grant insert (id, connection_id, sender_id, type, body, media_key, media_mime, media_width,
  media_height, media_duration_ms, activity_id) on public.messages to authenticated;

-- connections is itself limited to the caller's own rows.
create policy "Members read messages in their Connections" on public.messages for select to authenticated
  using (connection_id in (select id from public.connections));

-- The caller is an Active side of an accepted Connection with no Block either way.
create function public.can_send_in(connection_id uuid) returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.connections c
    join public.profiles me on me.id = auth.uid()
    where c.id = can_send_in.connection_id
      and c.status = 'accepted'
      and auth.uid() in (c.requester_id, c.addressee_id)
      and me.status = 'active' and me.deleted_at is null
      and not public.is_blocked(c.requester_id, c.addressee_id)
  );
$$;

revoke execute on function public.can_send_in(uuid) from public, anon;

create policy "Members send in their open Connections" on public.messages for insert to authenticated
  with check (sender_id = (select auth.uid()) and public.can_send_in(connection_id));

-- One row per side of an accepted Connection: read position and Mute.
create table public.connection_members (
  connection_id uuid not null references public.connections (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  last_read_at timestamptz,
  muted boolean not null default false,
  created_at timestamptz not null default now(),
  primary key (connection_id, user_id)
);
create index on public.connection_members (user_id);
alter table public.connection_members enable row level security;
revoke all on public.connection_members from anon, authenticated;
grant select on public.connection_members to authenticated;
grant update (last_read_at, muted) on public.connection_members to authenticated;

create policy "Members read both sides of their Connections" on public.connection_members
  for select to authenticated
  using (connection_id in (select id from public.connections));

create policy "Members update their own side" on public.connection_members for update to authenticated
  using (user_id = (select auth.uid()));

create function public.add_connection_members() returns trigger
language plpgsql
set search_path = ''
as $$
begin
  insert into public.connection_members (connection_id, user_id)
  values (new.id, new.requester_id), (new.id, new.addressee_id)
  on conflict do nothing;
  return null;
end;
$$;

create trigger add_members_on_accept after insert or update of status on public.connections
  for each row when (new.status = 'accepted') execute function public.add_connection_members();

-- Definer: Members cannot write realtime.messages, and realtime.send only warns on failure.
create function public.broadcast_message() returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  perform realtime.send(to_jsonb(new), 'message', 'connection:' || new.connection_id, true);
  return null;
end;
$$;

revoke execute on function public.broadcast_message() from public, anon, authenticated;

create trigger broadcast_on_insert after insert on public.messages
  for each row execute function public.broadcast_message();

-- Realtime admits a subscriber to connection:<id> only if this select succeeds with the topic set.
create policy "Members join their Connections' topics" on realtime.messages for select to authenticated
  using (
    topic = (select realtime.topic())
    and exists (select 1 from public.connections c where 'connection:' || c.id = (select realtime.topic()))
  );
